def page(path,title,desc,body,ld=None,extra=""):
    depth=path.count('/'); rel='../'*depth if path else ''
    url=BASE+path; lds=''.join('<script type="application/ld+json">%s</script>'%json.dumps(x) for x in (ld or []))
    nav=[('','Crop Calculator'),('crops/','Crops'),('skill-planner/','Skill Planner'),('guides/','Guides'),('about/','About')]
    h=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc)}"><link rel="canonical" href="{url}">
<meta property="og:type" content="website"><meta property="og:title" content="{html.escape(title)}"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:url" content="{url}"><meta property="og:site_name" content="Loftia Tools (fan-made)"><meta name="twitter:card" content="summary">
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'%3E%3Ccircle cx='8' cy='8' r='7' fill='%232f7a4a'/%3E%3C/svg%3E">
<link rel="stylesheet" href="{rel}assets/style.css">{lds}</head><body><header><div class="w"><a class="brand" href="{rel or './'}">Loftia Tools <span style="font-weight:400;font-size:.8rem">· fan-made</span></a><nav>{' · '.join(f'<a href="{rel}{p}">{n}</a>' if p else f'<a href="{rel or "./"}">{n}</a>' for p,n in nav)}</nav></div></header>
<main class="w">{body}<div class="ad-slot" aria-hidden="true"></div></main>
<footer><div class="w"><p><b>Unofficial fan site, not affiliated with Qloud Games or the Loftia developer.</b> Loftia and related names belong to their owners. Game data is from the Steam Next Fest demo and community sources (see <a href="{rel}about/#sources">sources</a>); values may change in Early Access.</p>
<p>Last updated: {UPD} · <a href="{rel}about/">About</a> · <a href="{rel}privacy/">Privacy</a> · <a href="{rel}guides/">Guides</a> · Official site: <a href="https://loftia.gg/" rel="nofollow">loftia.gg</a></p></div></footer>{extra.replace("REL",rel)}</body></html>'''
    d=os.path.join('site',path); os.makedirs(d,exist_ok=True); open(os.path.join(d,'index.html'),'w').write(h); return url
urls=[]
